layer.css:
[data-ryt="footer"] { color: color-mix(in srgb, var(--ryt-text) 85%, transparent); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: color-mix(in srgb, var(--ryt-text) 85%, transparent); font-family: var(--ryt-font-heading); font-size: 30px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-text) 85%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
